package org.brightstats.data;
import java.util.*;import com.google.gson.*;import org.brightstats.stats.LatentInteractionSem;
/** Explicit supported latent-likelihood schema; unknown modeling requests are rejected. */
public final class LatentInteractionInput {
 private LatentInteractionInput(){}
 private static void fields(JsonObject object,Set<String> allowed){for(String key:object.keySet())if(!allowed.contains(key))throw new IllegalArgumentException("Unsupported latent likelihood field: "+key);}
 private static LatentInteractionSem.Factor factor(JsonElement value){var object=value.getAsJsonObject();fields(object,Set.of("name","columns"));var name=object.get("name");if(name==null||!name.isJsonPrimitive()||!name.getAsJsonPrimitive().isString())throw new IllegalArgumentException("Name each latent measurement factor.");return new LatentInteractionSem.Factor(name.getAsString(),PlsModelInput.indices(object.get("columns")));}
 public static void requireCompleteSelected(JsonObject history,List<String> names,double[][] prepared,LatentInteractionSem.Model model){if(history==null)return;var original=PredictionInput.original(history,names,prepared);List<LatentInteractionSem.Factor> factors=new ArrayList<>(model.predictors());factors.add(model.outcome());for(var row:original)for(var factor:factors)for(int column:factor.columns()){if(column>=row.length)throw new IllegalArgumentException("Latent indicator binding is missing from the prepared source.");if(!Double.isFinite(row[column]))throw new IllegalArgumentException("Selected latent indicators contain imputed missing cells. Reprepare complete cases; this likelihood is not FIML/MAR correction.");}}
 public static LatentInteractionSem.Model model(JsonElement value){if(value==null||!value.isJsonObject())throw new IllegalArgumentException("Provide the latent likelihood model.");var object=value.getAsJsonObject();fields(object,Set.of("predictors","outcome","interactions"));List<LatentInteractionSem.Factor> predictors=new ArrayList<>();for(var item:object.getAsJsonArray("predictors"))predictors.add(factor(item));List<LatentInteractionSem.Interaction> interactions=new ArrayList<>();if(object.has("interactions"))for(var item:object.getAsJsonArray("interactions")){var term=item.getAsJsonObject();fields(term,Set.of("first","second"));interactions.add(new LatentInteractionSem.Interaction(PlsModelInput.index(term.get("first")),PlsModelInput.index(term.get("second"))));}return new LatentInteractionSem.Model(predictors,factor(object.get("outcome")),interactions);}
 public static LatentInteractionSem.Options options(JsonElement value){var d=LatentInteractionSem.Options.defaults();if(value==null||value.isJsonNull())return d;var o=value.getAsJsonObject();fields(o,Set.of("nodes","checkNodes","maxIterations","starts","gradientTolerance","functionTolerance","integrationTolerance","confidence","predictorDistribution","predictorDegreesOfFreedom"));return new LatentInteractionSem.Options(StatisticalInput.integer(o,"nodes",d.nodes()),StatisticalInput.integer(o,"checkNodes",d.checkNodes()),StatisticalInput.integer(o,"maxIterations",d.maxIterations()),StatisticalInput.integer(o,"starts",d.starts()),StatisticalInput.number(o,"gradientTolerance",d.gradientTolerance()),StatisticalInput.number(o,"functionTolerance",d.functionTolerance()),StatisticalInput.number(o,"integrationTolerance",d.integrationTolerance()),StatisticalInput.number(o,"confidence",d.confidence()),StatisticalInput.enumeration(o,"predictorDistribution",LatentInteractionSem.PredictorDistribution.class,d.predictorDistribution()),StatisticalInput.number(o,"predictorDegreesOfFreedom",d.predictorDegreesOfFreedom()));}
}
